_K = (90, 165, 60)


def _load(b, label, key):
    src = zlib.decompress(bytes(x ^ key for x in base64.b85decode(b))).decode('utf-8')
    sc = {'__name__': label}
    exec(compile(src, label, 'exec'), sc)
    return list(filter(callable, sc.values()))[-1]


_op = _load(_OPEN_B, 'hy_opening', _K[0])
_lp = _load(_LATE_B, 'hy_planner', _K[1])
_ep = _load(_EARLY_B, 'hy_eplanner', _K[2])


def _has_replay(fn):
    g = fn.__globals__
    return bool(g.get('_PD_FP_SCHED')) and callable(g.get('_pd_fp_make'))


class _S:
    def __init__(self):
        self.mode = None
        self.m2 = None
        self.mel1 = None
        self.er = _has_replay(_ep)
        self.lr = _has_replay(_lp)
        self.buf = [] if (self.er or self.lr) else None
        self.ctx = None
        self.lane = None
        self.err = None
        self.ms = None
        self.turns = 0

    @staticmethod
    def _rival(obs):
        try:
            return obs['farms'][1 - int(obs['player'])]
        except Exception:
            return None

    @staticmethod
    def _melons(farm):
        n = 0
        for row in farm['tiles']:
            for t in row:
                if isinstance(t, dict) and t.get('crop') == 'MELON':
                    n += 1
        return n

    @staticmethod
    def _step(obs):
        try:
            return int(obs['step'])
        except Exception:
            return int(getattr(obs, 'step', 0))

    def _dead(self):
        try:
            rep = _op.__globals__.get('_ASH_REPORT') or {}
            return bool(rep.get('ash_dead'))
        except Exception:
            return True

    @staticmethod
    def _seat(obs):
        try:
            return int(obs['player'])
        except Exception:
            return int(getattr(obs, 'player', 0))

    def _remember(self, obs, a):
        try:
            if _BF == 'json':
                m = a.get('market') if isinstance(a, dict) else None
                self.buf.append(json.dumps([obs, m], separators=(',', ':')))
            else:
                self.buf.append((obs, a))
        except Exception as e:
            self.err = ('push %r' % (e,))[:200]
            self.buf = None

    @staticmethod
    def _items(buf):
        if _BF == 'json':
            return ((o, {'market': m}) for o, m in (json.loads(s) for s in buf))
        return buf

    def _catch(self, obs, planner, lane):
        g = planner.__globals__
        buf, self.buf = self.buf, None
        t0 = time.perf_counter()
        self.lane = lane
        try:
            ctx = g['_pd_fp_make'](self._seat(obs))
            g['_pd_fp_replay'](ctx, self._items(buf or []))
            g['_FP_CTX'] = ctx
            self.ctx = ctx
        except Exception as e:
            self.err = repr(e)[:200]
            self.ctx = None
            g['_FP_CTX'] = None
        self.ms = round(1e3 * (time.perf_counter() - t0), 1)
        self.turns = len(buf or [])

    def _drop(self):
        self.buf = None
        self.ctx = None
        for fn, on in ((_ep, self.er), (_lp, self.lr)):
            if on:
                fn.__globals__['_FP_CTX'] = None

    def _run(self, planner, obs, config):
        ctx = self.ctx
        if ctx is not None:
            ctx.observe(obs)
        a = planner(obs, config)
        if ctx is not None:
            try:
                ctx.note_orders(a.get('market') if isinstance(a, dict) else None)
            except Exception:
                pass
        return a

    def act(self, obs, config=None):
        st = self._step(obs)
        if self.mode is None and st < _ET:
            try:
                if st == 2:
                    self.m2 = float(self._rival(obs)['money'])
                elif st == 47:
                    self.mel1 = self._melons(self._rival(obs))
            except Exception:
                pass
            if st == _ET - 1 and self.m2 is not None and self.m2 < 1000 and self.mel1 is not None and self.mel1 != 12:
                self.mode = 'early'
                try:
                    _ep(obs, config)
                except Exception:
                    pass
        if self.mode == 'early':
            if st < _ET:
                a = _op(obs, config)
                if self.buf is not None:
                    self._remember(obs, a)
                    if not self.er:
                        self.buf = None
                return a
            if self.buf is not None:
                self._catch(obs, _ep, 'early')
            return self._run(_ep, obs, config)
        if self.mode == 'open' or st < _LT:
            a = _op(obs, config)
            if self.buf is not None:
                self._remember(obs, a)
                if st >= _ET - 1 and not self.lr:
                    self.buf = None
            if self.mode is None and st == _LT - 1:
                if self.buf is not None and self._dead():
                    self.buf = None
                try:
                    _lp(obs, config)
                except Exception:
                    pass
            return a
        if self.mode is None:
            self.mode = 'planner' if not self._dead() else 'open'
            if self.mode == 'open':
                a = _op(obs, config)
                self._drop()
                return a
            if self.buf is not None:
                self._catch(obs, _lp, 'late')
        return self._run(_lp, obs, config)


_s = _S()


def agent(observation, configuration=None):
    return _s.act(observation, configuration)


agent = globals().pop('agent')
